#!/usr/bin/env bash

# This script requires a hostfile named "hosts" in the current working directory. 
# The hostfile should contain a list of hostnames or IP addresses, one per line,
# that you want to use for running the script.
# Example hostfile:
#
# node1 slots=1
# node2 slots=1
# node3 slots=1
#
# It also expects the result folder
#
# mkdir -p result
#
# And the key file to be generated by the setup command. You can generate it with the following command:
# 
# mpirun -np 1 \
#  ../../target/release/examples/ass_snark setup \
#  --log-instance-size 24 \
#  --log-num-workers-per-party 0 \
#  --log-num-public-workers 1 \
#  --key-out inst_folder


set -euo pipefail

HOSTFILE="$(pwd)/hosts"
INSTANCE_SIZE=24
WORKERS_PER_PARTY=0
PUBLIC_WORKERS=1
KEY_FILE="$(pwd)/examples/ass_snark/inst_folder/inst_24_0_1/test"

# Adjust if you want a different thread count per process.
export RAYON_NUM_THREADS=8

mpirun 
  --hostfile "$HOSTFILE" 
  -np 3 
  --map-by ppr:1:node 
  --bind-to none 
  -x RAYON_NUM_THREADS 
  bash -lc '
    set -e
    cd "'"$(pwd)"'/examples/ass_snark"
    exec ../../target/release/examples/ass_snark work 
      --log-instance-size '"$INSTANCE_SIZE"' 
      --log-num-workers-per-party '"$WORKERS_PER_PARTY"' 
      --log-num-public-workers '"$PUBLIC_WORKERS"' 
      --key-file "'"$KEY_FILE"'" 
      --worker-id "${OMPI_COMM_WORLD_RANK}" 
      --local 0
  '

